      await fs.writeFile(Buffer.concat([root, Buffer.from('/dir-\xfe/inside', 'latin1')]), 'z');
      const res = await list();
      assert.equal(res.status, 200);
      assert.deepEqual(res.json.map((b) => b.key), ['ok']);
